-- Registration recitation test: longer ayahs from Surah Maryam (19) to
-- Surah Al-Furqan (25), 3 per surah (75–175 letters each, sajdah ayahs
-- excluded), replacing the short ones. Text: Tanzil "simple" edition with
-- full tashkeel; translation: Saheeh International (via api.alquran.cloud).
-- Old ayahs are kept (existing recitations reference them) but taken out
-- of rotation.
alter table public.quran_ayahs add column in_rotation boolean not null default true;
update public.quran_ayahs set in_rotation = false;

